class Solution {
  public int findMinMoves(int[] machines) {
    long total = 0;
    for (int x : machines) total += x;
    if (total % machines.length != 0) return -1;
    long target = total / machines.length, balance = 0;
    long answer = 0;
    for (int x : machines) {
      long delta = x - target;
      balance += delta;
      answer = Math.max(answer, Math.max(Math.abs(balance), delta));
    }
    return (int) answer;
  }
}
